/**
 * FATISH CAKES: Smooth, fast image component.
 *
 * - Serves responsive WebP (srcset) generated by scripts/optimize-images.py
 * - Shows a tiny blurred preview instantly, then sharpens into the real photo
 * - Lazy-loads below-the-fold images; `priority` loads above-the-fold ones first
 * - Images already in the browser cache skip the animation (no flicker)
 *
 * Drop-in replacement for <img>: same props, plus `sizes` and `priority`.
 */

import React, { useCallback, useLayoutEffect, useRef, useState } from 'react';
import { imageManifest } from '../data/imageManifest.ts';

type ImgProps = Omit<React.ImgHTMLAttributes<HTMLImageElement>, 'src' | 'srcSet'> & {
  src: string;
  /** Tells the browser how wide the image renders so it downloads the right size. */
  sizes?: string;
  /** Above-the-fold image (hero): load immediately with high priority. */
  priority?: boolean;
};

const SOURCE_RE = /\/assets\/aistudio\/([^/]+)\.(?:png|jpe?g|webp)$/i;
const DEFAULT_SIZES = '(min-width: 1024px) 33vw, (min-width: 640px) 50vw, 100vw';

export function getImageSources(src: string) {
  const match = SOURCE_RE.exec(src);
  const meta = match ? imageManifest[match[1]] : undefined;
  if (!match || !meta) return null;
  const name = match[1];
  const url = (w: number) => `/assets/img/${name}-${w}.webp`;
  const widths = meta.widths;
  return {
    meta,
    src: url(widths[Math.min(2, widths.length - 1)]),
    srcSet: widths.map((w) => `${url(w)} ${w}w`).join(', '),
  };
}

export const Img: React.FC<ImgProps> = ({
  src,
  sizes,
  priority = false,
  className = '',
  style,
  alt,
  onLoad,
  onError,
  ...rest
}) => {
  const optimized = getImageSources(src);
  const ref = useRef<HTMLImageElement | null>(null);
  // 'pending' -> blurred preview, 'reveal' -> animate to sharp, 'done' -> nothing to do
  const [phase, setPhase] = useState<'pending' | 'reveal' | 'done'>(optimized ? 'pending' : 'done');

  // New src (lightbox next/prev, modal reuse): restart the blur-up for the new photo.
  const [prevSrc, setPrevSrc] = useState(src);
  if (prevSrc !== src) {
    setPrevSrc(src);
    setPhase(optimized ? 'pending' : 'done');
  }

  // Already cached by the browser? Skip the animation entirely.
  useLayoutEffect(() => {
    const el = ref.current;
    if (el && el.complete && el.naturalWidth > 0) setPhase('done');
  }, [src]);

  const handleLoad = useCallback(
    (e: React.SyntheticEvent<HTMLImageElement>) => {
      setPhase((p) => (p === 'pending' ? 'reveal' : p));
      onLoad?.(e);
    },
    [onLoad]
  );

  const handleError = useCallback(
    (e: React.SyntheticEvent<HTMLImageElement>) => {
      setPhase('done');
      onError?.(e);
    },
    [onError]
  );

  const phaseClass = phase === 'pending' ? 'img-pending' : phase === 'reveal' ? 'img-reveal' : '';
  const mergedStyle: React.CSSProperties | undefined = optimized
    ? {
        backgroundImage: `url("${optimized.meta.blur}")`,
        backgroundSize: 'cover',
        backgroundPosition: 'center',
        ...style,
      }
    : style;

  return (
    <img
      {...rest}
      ref={ref}
      src={optimized ? optimized.src : src}
      srcSet={optimized?.srcSet}
      sizes={optimized ? sizes ?? DEFAULT_SIZES : undefined}
      alt={alt ?? ''}
      width={optimized ? optimized.meta.w : rest.width}
      height={optimized ? optimized.meta.h : rest.height}
      loading={priority ? 'eager' : 'lazy'}
      decoding={priority ? 'sync' : 'async'}
      fetchPriority={priority ? 'high' : 'auto'}
      className={`${className} ${phaseClass}`.trim()}
      style={mergedStyle}
      onLoad={handleLoad}
      onError={handleError}
    />
  );
};
